def update_templates_cashout_and_freeplay(min_cashout=35, freeplay_amount=5):
    """
    Dynamically updates all email templates in real time when the user changes
    Minimum Cashout or Freeplay Bonus in Dashboard Settings.
    """
    global TEMPLATES
    import os, json

    cashout_str = f"${min_cashout}"
    freeplay_str = f"${freeplay_amount} Freeplay"

    for t in TEMPLATES:
        # 1. Update Subject
        sub = t.get("subject", "")
        sub = re.sub(r'\$\d+\s*(?:min\s+cashout|minimum\s+cashout)', f'{cashout_str} min cashout', sub, flags=re.I)
        sub = re.sub(r'\$\d+\s*Min\s*Cashout', f'{cashout_str} Min Cashout', sub, flags=re.I)
        sub = re.sub(r'\$\d+\s*Cashout', f'{cashout_str} Cashout', sub, flags=re.I)
        sub = re.sub(r'\$\d+\s*Freeplay', freeplay_str, sub, flags=re.I)
        t["subject"] = sub

        # 2. Update Preview Text
        prev = t.get("preview_text", "")
        prev = re.sub(r'\$\d+\s*(?:minimum\s+cashouts?|min\s+cashouts?|cashouts?)', f'{cashout_str} cashouts', prev, flags=re.I)
        prev = re.sub(r'\$\d+\s*Freeplay', freeplay_str, prev, flags=re.I)
        t["preview_text"] = prev

        # 3. Update Plain Text
        pt = t.get("plain_text", "")
        pt = re.sub(r'\$\d+\s*(?:minimum\s+cashout|min\s+cashout)', f'{cashout_str} minimum cashout', pt, flags=re.I)
        pt = re.sub(r'\$\d+\s*(?:Minimum\s+Cashout|Min\s+Cashout)', f'{cashout_str} Minimum Cashout', pt, flags=re.I)
        pt = re.sub(r'starting at (?:just )?\$\d+', f'starting at just {cashout_str}', pt, flags=re.I)
        pt = re.sub(r'from (?:just )?\$\d+', f'from just {cashout_str}', pt, flags=re.I)
        pt = re.sub(r'reach (?:just )?\$\d+', f'reach {cashout_str}', pt, flags=re.I)
        pt = re.sub(r'hit (?:just )?\$\d+', f'hit {cashout_str}', pt, flags=re.I)
        pt = re.sub(r'above \$\d+', f'above {cashout_str}', pt, flags=re.I)
        pt = re.sub(r'\$\d+\s*Freeplay', freeplay_str, pt, flags=re.I)
        t["plain_text"] = pt

        # 4. Update HTML Body
        ht = t.get("html", "")
        ht = re.sub(r'\$\d+\s*(?:minimum\s+cashout|min\s+cashout)', f'{cashout_str} minimum cashout', ht, flags=re.I)
        ht = re.sub(r'\$\d+\s*(?:Minimum\s+Cashout|Min\s+Cashout)', f'{cashout_str} Minimum Cashout', ht, flags=re.I)
        ht = re.sub(r'starting at (?:just )?\$\d+', f'starting at just {cashout_str}', ht, flags=re.I)
        ht = re.sub(r'from (?:just )?\$\d+', f'from just {cashout_str}', ht, flags=re.I)
        ht = re.sub(r'reach (?:just )?\$\d+', f'reach {cashout_str}', ht, flags=re.I)
        ht = re.sub(r'hit (?:just )?\$\d+', f'hit {cashout_str}', ht, flags=re.I)
        ht = re.sub(r'above \$\d+', f'above {cashout_str}', ht, flags=re.I)
        ht = re.sub(r'\$\d+\s*Freeplay', freeplay_str, ht, flags=re.I)
        ht = re.sub(r'<title>[^<]*</title>', f'<title>{sub}</title>', ht, flags=re.I)
        t["html"] = ht

    # Persist updated TEMPLATES to disk
    try:
        base_dir = os.path.dirname(os.path.abspath(__file__))
        fpath = os.path.join(base_dir, "templates_data.py")
        with open(fpath, "r", encoding="utf-8") as f_in:
            src = f_in.read()
        m_start = "TEMPLATES = "
        m_end = "def get_templates():"
        i_start = src.find(m_start)
        i_end = src.find(m_end)
        if i_start != -1 and i_end != -1:
            new_src = src[:i_start + len(m_start)] + json.dumps(TEMPLATES, indent=4, ensure_ascii=False) + "\n\n" + src[i_end:]
            with open(fpath, "w", encoding="utf-8") as f_out:
                f_out.write(new_src)
    except Exception as e:
        print(f"Error persisting templates: {e}")

    return TEMPLATES
